// Reads the brief (from Telegram or the API) and writes the instructions for the AI.
const input = $input.first().json;
const cfg = input.cfg || {};
const fromApi = input.body !== undefined && input.headers !== undefined;
const src = fromApi ? (input.body || {}) : input;

let product, benefit, audience, language, style;
if (fromApi) {
  ({ product, benefit, audience, language, style } = src);
} else {
  [product, benefit, audience, language, style] = String(src.args || '').split('|').map(s => s.trim());
}
const clean = (s, n) => String(s ?? '').replace(/\s+/g, ' ').trim().slice(0, n);
product = clean(product, 200);
benefit = clean(benefit, 300);
audience = clean(audience, 200);
language = clean(language, 40) || 'English';
style = clean(style, 300);          // optional, for example "luxurious, slow, no voiceover"
if (!product) {
  throw new Error('Tell me the product, like this → /ad Vanilla Oat Cold Brew | smooth, never bitter | students | English');
}
const languageRule = /taglish/i.test(language)
  ? 'Taglish (the natural Filipino-English mix spoken in Manila)'
  : language;

// Short code the owner can type, without look-alike characters (no 0/O, 1/I).
const alphabet = 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';
const content_id = 'AD-' + Array.from({ length: 5 }, () => alphabet[Math.floor(Math.random() * alphabet.length)]).join('');

const system = `You are a senior short-form video ad creative working for the brand "${cfg.brand_name}". Brand voice: ${cfg.brand_voice}.
You write 24-second vertical video ads for TikTok, Reels and Shorts. Every ad has exactly 3 scenes of 8 seconds. Each scene is generated separately with Google Veo (in Google Flow). Captions are added later in editing.

Return ONLY a JSON object with exactly this shape:
{
  "angle": "the single idea of the ad, in one sentence",
  "scenes": [
    { "role": "hook", "on_screen_text": "", "voiceover": "", "veo_prompt": "" },
    { "role": "benefit", "on_screen_text": "", "voiceover": "", "veo_prompt": "" },
    { "role": "cta", "on_screen_text": "", "voiceover": "", "veo_prompt": "" }
  ],
  "caption": "",
  "hashtags": ["#example"]
}

Rules:
- Scene 1 (hook) stops the scroll with a relatable problem or a surprising claim. Scene 2 (benefit) shows the product solving it. Scene 3 (cta) shows the happy result and invites action.
- on_screen_text: at most 8 words, punchy, no emoji, no hashtags. Language: ${languageRule}.
- voiceover: one natural spoken sentence, at most 18 words. Language: ${languageRule}. Use an empty string when the style notes ask for no voiceover.
- Style notes from the owner, when given, override the brand voice for mood, pacing, visuals and sound. Apply them in every veo_prompt.
- If the style notes ask for no voiceover, no narration, no talking, no dialogue or no commentary: set every voiceover to "" and, in every veo_prompt, write "No dialogue, no narration. Only music and natural ambient sound." instead of a spoken line.
- veo_prompt: ALWAYS in English, one paragraph of 60 to 90 words. Start with "Vertical 9:16 video, 8 seconds." Then describe the subject and action, the setting, the camera movement, the lighting and mood, and the audio. Describe the product with the same exact look in every scene (shape, color, material, label color) so it stays consistent. Include the voiceover as narration or as a line a person says, in double quotes. End with "No on-screen text, no subtitles, no logos."
- Use only facts from the brief. No real brand names, no celebrities, no medical claims, no guaranteed results.
- caption: 1 or 2 sentences plus the call to action, at most 220 characters. Language: ${languageRule}.
- hashtags: 5 to 8 relevant hashtags, lowercase, each starting with #.`;

const user = [
  `Product: ${product}`,
  `Key benefit: ${benefit || 'not given, infer one sensible benefit from the product itself'}`,
  `Target audience: ${audience || 'not given, pick the most likely buyers'}`,
  `Call to action: ${cfg.brand_cta}`,
  `Style notes from the owner: ${style || 'none'}`,
].join('\n');

const llm_request = {
  model: cfg.llm_model,
  temperature: 0.8,
  // A JSON schema forces the model to answer in exactly this shape.
  response_format: { type: 'json_schema', json_schema: { name: 'ad_script_pack', schema: {
    type: 'object',
    required: ['angle', 'scenes', 'caption', 'hashtags'],
    properties: {
      angle: { type: 'string' },
      scenes: { type: 'array', minItems: 3, maxItems: 3, items: {
        type: 'object',
        required: ['role', 'on_screen_text', 'voiceover', 'veo_prompt'],
        properties: {
          role: { type: 'string' },
          on_screen_text: { type: 'string' },
          voiceover: { type: 'string' },
          veo_prompt: { type: 'string' },
        },
      } },
      caption: { type: 'string' },
      hashtags: { type: 'array', items: { type: 'string' } },
    },
  } } },
  messages: [{ role: 'system', content: system }, { role: 'user', content: user }],
};
if (cfg.llm_reasoning_effort) llm_request.reasoning_effort = cfg.llm_reasoning_effort;

return [{ json: {
  content_id,
  chat_id: String(src.chat_id || cfg.owner_chat_id || ''),
  source: fromApi ? 'api' : 'telegram',
  created_at: $now.toFormat('yyyy-MM-dd HH:mm'),
  brief: { product, benefit, audience, language, style },
  cta: cfg.brand_cta,
  llm_url: String(cfg.llm_base_url || '').replace(/\/+$/, '') + '/chat/completions',
  llm_request,
} }];

// The AI answers with text. This checks it really is the script pack we asked for.
const res = $input.first().json;
const job = $('Build Brief').first().json;

let raw = res.choices?.[0]?.message?.content ?? '';
if (Array.isArray(raw)) raw = raw.map(part => part.text || '').join('');
raw = String(raw).replace(/<think>[\s\S]*?<\/think>/gi, '').trim();   // some models think out loud first

const start = raw.indexOf('{');
const end = raw.lastIndexOf('}');
let pack;
try {
  pack = JSON.parse(raw.slice(start, end + 1));
} catch (e) {
  throw new Error('The AI returned a script I could not read. Please send /ad again.');
}

const clean = (s, n) => String(s ?? '').replace(/\s+/g, ' ').trim().slice(0, n);
const roles = ['hook', 'benefit', 'cta'];
const scenes = (Array.isArray(pack.scenes) ? pack.scenes : []).slice(0, 3).map((s, i) => ({
  n: i + 1,
  role: roles[i],
  on_screen_text: clean(s?.on_screen_text, 80),
  voiceover: clean(s?.voiceover, 220),
  veo_prompt: clean(s?.veo_prompt, 1200),
}));
if (scenes.length < 3 || scenes.some(s => !s.on_screen_text || !s.veo_prompt)) {
  throw new Error('The AI returned an incomplete script (I need 3 full scenes). Please send /ad again.');
}

let hashtags = Array.isArray(pack.hashtags) ? pack.hashtags : String(pack.hashtags || '').split(/[\s,]+/);
hashtags = [...new Set(
  hashtags.map(h => '#' + String(h).replace(/[^\p{L}\p{N}_]/gu, '').toLowerCase()).filter(h => h.length > 1)
)].slice(0, 8);

return [{ json: {
  content_id: job.content_id,
  chat_id: job.chat_id,
  source: job.source,
  created_at: job.created_at,
  brief: job.brief,
  angle: clean(pack.angle, 300),
  scenes,
  caption: clean(pack.caption, 400),
  hashtags,
  cta: job.cta,
  model: res.model || job.llm_request.model,
} }];

// Builds the Telegram messages. Each Veo prompt gets its own message in a code block,
// because tapping a code block in Telegram copies it, ready to paste into Google Flow.
const p = $('Parse Script Pack').first().json;
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const titles = ['Hook', 'Benefit', 'Call to action'];

const overview = [
  `🎬 <b>Ad script ready</b> · <code>${p.content_id}</code>`,
  `<b>Product:</b> ${esc(p.brief.product)}`,
  `<b>Idea:</b> ${esc(p.angle)}`,
  ...(p.brief.style ? [`<b>Style:</b> ${esc(p.brief.style)}`] : []),
  '',
  ...p.scenes.flatMap((s, i) => [
    `<b>Scene ${s.n} · ${titles[i]}</b>`,
    `📝 ${esc(s.on_screen_text)}`,
    s.voiceover ? `🎙 ${esc(s.voiceover)}` : '🎙 <i>No voiceover (music and ambient sound only)</i>',
    '',
  ]),
  '<b>Caption</b>',
  esc(p.caption),
  esc(p.hashtags.join(' ')),
].join('\n');

const prompts = p.scenes.map(s =>
  `🎥 <b>Scene ${s.n} prompt</b> (tap to copy, paste into Google Flow)\n<code>${esc(s.veo_prompt)}</code>`
);

const next = [
  '✅ <b>Next step</b>',
  'Generate the 3 clips in Google Flow (Veo, portrait 9:16), then send them here in order: scene 1, 2, 3.',
  'I will add the captions and the end card.',
  '',
  `No clips yet? Send <code>/demo ${p.content_id}</code> to preview with placeholder clips.`,
].join('\n');

return [overview, ...prompts, next].map(text => ({ json: { chat_id: p.chat_id, text } }));

// What the workflow hands back to whoever called it (the router or the API).
const p = $('Parse Script Pack').first().json;
return [{ json: {
  ok: true,
  content_id: p.content_id,
  angle: p.angle,
  scenes: p.scenes,
  caption: p.caption,
  hashtags: p.hashtags,
  model: p.model,
} }];
